import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In {dimension}-dimensional Euclidean space, consider the axis-aligned orthogonal box whose edge lengths along the coordinate axes are {axis_lengths}. Let T be the set of all triangles formed by choosing any three distinct vertices of this box (viewed as embedded in the ambient space). Compute the exact integer value of the sum of the squared areas of all triangles in T.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose dimension between 3 and 6 to keep numbers reasonable but nontrivial
d = rng.randint(3, 6)
# Generate edge lengths as positive integers in [1, 9]
# Ensure at least two distinct values to avoid trivial symmetric cases
# Retry if constraints not met
for _ in range(100):
    a_list = [rng.randint(1, 9) for _ in range(d)]
    # At least two distinct and not all equal
    if len(set(a_list)) >= 2:
        # Also avoid the extremely trivial case where all are 1 in low d
        if not all(x == 1 for x in a_list):
            axis_lengths = ", ".join(str(x) for x in a_list)
            return {
                'dimension': d,
                'axis_lengths': axis_lengths,
                # Provide raw list for verifier cross-check and computation
                'a_list': a_list
            }
# As a fallback (should not happen), force a nontrivial assignment
a_list = [2] * (d - 1) + [3]
axis_lengths = ", ".join(str(x) for x in a_list)
return {
    'dimension': d,
    'axis_lengths': axis_lengths,
    'a_list': a_list
}

    def verifier(assign):
# Validate keys
if 'dimension' not in assign or 'axis_lengths' not in assign:
    # Missing required placeholders
    return False, None  # missing data
d = assign['dimension']
axis_lengths_str = assign['axis_lengths']
# Basic type/domain checks
if not isinstance(d, int):
    return False, None  # dimension must be int
if d < 3 or d > 10:
    return False, None  # enforce nontrivial ambient dimension and avoid overflow
if not isinstance(axis_lengths_str, str):
    return False, None  # axis_lengths must be a string
# Parse axis lengths from the string, allow spaces
try:
    parts = [p.strip() for p in axis_lengths_str.split(',') if p.strip() != '']
    a_from_str = [int(p) for p in parts]
except Exception:
    return False, None  # unparsable axis lengths
if len(a_from_str) != d:
    return False, None  # mismatch between dimension and number of lengths
if any(x <= 0 for x in a_from_str):
    return False, None  # lengths must be positive
# If generator provided a_list, cross-check consistency
if 'a_list' in assign:
    a_list = assign['a_list']
    if not isinstance(a_list, list) or len(a_list) != d or any(not isinstance(x, int) for x in a_list):
        return False, None  # invalid internal data
    if a_list != a_from_str:
        return False, None  # axis_lengths string does not match raw list
else:
    a_list = a_from_str
# Enforce nontriviality: at least two distinct edge lengths
if len(set(a_list)) < 2:
    return False, None  # trivial uniform case disallowed
# Compute sum of squared areas using the derived closed form
# For an axis-aligned d-dimensional orthogonal box with edge lengths a_i,
# the sum over all unordered triples of vertices of the squared triangle areas equals
# 2^{3d-6} * sum_{i<j} (a_i^2 * a_j^2).
# Derivation uses the identity ||x \wedge y||^2 = ||x||^2||y||^2 - (x·y)^2 and symmetry over vertices.
# Compute sum_{i<j} a_i^2 a_j^2
s_pairs = 0
a2 = [x * x for x in a_list]
for i in range(d):
    for j in range(i + 1, d):
        s_pairs += a2[i] * a2[j]
if s_pairs <= 0:
    return False, None  # should not be zero for positive lengths and d>=3
# Compute factor 2^{3d-6}
factor_exp = 3 * d - 6
# To avoid extremely large answers, ensure exponent is reasonable
if factor_exp < 0:
    return False, None
factor = 1 << factor_exp  # power of two
answer = factor * s_pairs
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

